import 'package:flutter/foundation.dart';
import '../models/hall_query.dart'; import '../models/page_result.dart'; import '../models/photographer.dart'; import '../models/photographer_query.dart'; import '../models/studio_hall.dart'; import '../repositories/hall_repository.dart'; import '../repositories/photographer_repository.dart';
enum LoadStatus{idle,loading,success,error}
class HallListNotifier extends ChangeNotifier{HallListNotifier(this._repo);final HallRepository _repo;HallQuery _query=const HallQuery();PageResult<StudioHall> _result=PageResult.empty();LoadStatus _status=LoadStatus.idle;String? _error;final Set<int> _selected={};HallQuery get query=>_query;PageResult<StudioHall> get result=>_result;LoadStatus get status=>_status;String? get error=>_error;Set<int> get selected=>Set.unmodifiable(_selected);bool get hasSelection=>_selected.isNotEmpty;Future<void> applyQuery(HallQuery q)async{_query=q;_selected.clear();await load();}Future<void> load()async{_status=LoadStatus.loading;_error=null;notifyListeners();try{_result=await _repo.find(_query);_status=LoadStatus.success;}catch(e){_error='Не удалось загрузить залы: $e';_status=LoadStatus.error;}notifyListeners();}void toggle(int id){if(!_selected.remove(id))_selected.add(id);notifyListeners();}void selectAll(Iterable<int> ids){_selected..clear()..addAll(ids);notifyListeners();}void clear(){_selected.clear();notifyListeners();}Future<void> softDelete(int id)async{await _repo.softDelete(id);_selected.remove(id);await load();}Future<void> restore(int id)async{await _repo.restore(id);await load();}Future<void> hardDelete(int id)async{await _repo.hardDelete(id);_selected.remove(id);await load();}Future<void> deleteSelected(bool hard)async{if(hard){await _repo.hardDeleteMany(_selected.toList());}else{await _repo.softDeleteMany(_selected.toList());}_selected.clear();await load();}}
